pub(super) fn closed_backend<'a>(
    rig: &'a Rig,
    now: &[Value],
    delay: &str,
    later: &str,
    then: Then,
) -> PhysicalBackend<'a> {
    assert_eq!(delay, "0.3");
    assert!(matches!(then, Then::Close));
    assert_eq!(now.len(), 1);
    assert!(later.is_empty());
    let (driver, script) = Driver::prepare_with_close(rig, now, later, true);
    let clock = Rc::clone(&driver.state);
    PhysicalBackend::new_with_clock(
        rig.config(script),
        &rig.assets,
        Box::new(Recording(rig.starts.clone())),
        move || MonoTime::from_micros(clock.now.get()),
    )
    .with_fixture_driver(driver)
    .unwrap()
}

