    #[test]
    fn a_marker_and_enqueue_or_dropped_notice_peer_cannot_prove_channel_closure() {
        let rig = Rig::new("disp-close-clock-no-token");
        let (mut driver, _) = Driver::prepare_with_close(&rig, &[start_line()], "", true);
        let sender = driver.relay_channel_closed_observer().unwrap();
        fs::write(&driver.later_marker, LATER).unwrap();
        let enqueued = AtomicU64::new(1);
        assert!(!driver.written_and_closed_once(&enqueued).unwrap());
        assert!(!driver.closed_observed);
